package com.brasa.restaurant.config;import com.brasa.restaurant.enums.Enums.*;import com.brasa.restaurant.model.*;import com.brasa.restaurant.repository.Repositories.*;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;@Configuration public class BootstrapConfig{@Bean CommandLineRunner bootstrap(RestauranteRepository rr,UsuarioRepository ur,MesaRepository mr,PasswordEncoder encoder){return args->{if(rr.count()>0)return;Restaurante r=new Restaurante();r.setNome("Restaurante Inicial");r.setSlug("meu-restaurante");rr.save(r);Usuario admin=new Usuario();admin.setRestauranteId(r.getId());admin.setNome("Administrador");admin.setEmail("admin@restaurante.com");admin.setSenhaHash(encoder.encode("Admin@123"));admin.setPerfil(Perfil.ADMIN);ur.save(admin);Usuario k=new Usuario();k.setRestauranteId(r.getId());k.setNome("Cozinha");k.setEmail("cozinha@restaurante.com");k.setSenhaHash(encoder.encode("Cozinha@123"));k.setPerfil(Perfil.COZINHA);ur.save(k);for(int i=1;i<=15;i++){Mesa m=new Mesa();m.setRestauranteId(r.getId());m.setNumero(i);mr.save(m);}};}}
